/// <summary>
/// The display transform that compresses scene radiance into the screen's range.
/// </summary>
public enum ToneMapping : uint
{
    /// <summary>
    /// Filmic ACES-style curve with a soft toe and highlight desaturation, similar to Unreal's default; the most cinematic.
    /// </summary>
    Filmic = 0,
    /// <summary>
    /// Khronos PBR Neutral: keeps material colours accurate up to bright highlights.
    /// </summary>
    Neutral = 1,
    /// <summary>
    /// Narkowicz's per-channel ACES fit (the legacy curve; saturated highlights).
    /// </summary>
    AcesFit = 2,
    /// <summary>
    /// AgX as Blender 5.1 forms it (Cycles' default view): keeps mid grey, bends bright saturated light smoothly towards white instead of clipping its hue.
    /// </summary>
    Agx = 3,
    /// <summary>
    /// AgX with Blender's Punchy look: deeper shadows and more contrast.
    /// </summary>
    AgxPunchy = 4,
    /// <summary>
    /// AgX with Blender's Medium High Contrast look: contrast 1.2 about mid grey.
    /// </summary>
    AgxMediumHighContrast = 5,
}

